package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import java.nio.file.Path;
import java.util.*;
final class ChangeSchedulingBrowserAcceptance {
 static Map<String,Object> plan(){return map("revision",0,"record_revision",0,"implementation","Deploy reviewed release","impact","Short restart","backout","Restore prior image","test","Verify all service checks","impact_score",2,"likelihood",2,"ready",true);}
 static void run(BrowserTest h)throws Exception{
  String ci,id;try(var db=h.store.open()){String admin=PlatformFoundationTest.bind(db);ci=Service.create(db,"cmdb_ci",map("short_description","Payment service <script>"),"admin").get("sys_id").toString();id=Service.create(db,"change_request",map("short_description","Schedule payment upgrade"),"admin").get("sys_id").toString();ChangePlanning.save(db,id,plan());for(var time:List.of(List.of("Maintenance","08:00","18:00"),List.of("Freeze","10:00","11:00")))ServiceClocks.calendar(db,admin,map("name",time.get(0),"calendar",map("zone","UTC","start",time.get(1),"end",time.get(2),"days",List.of(1,2,3,4,5),"holidays",List.of())));db.connection.commit();}
  try(var p=Playwright.create();var browser=p.chromium().launch();var context=browser.newContext()){
   var page=context.newPage();h.login(page,"admin");page.navigate(h.base()+"/record/cmdb_ci/"+ci);page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Manage change windows")).press("Enter");for(String kind:List.of("maintenance","blackout")){var form=page.locator("#new-window");form.getByLabel("Window name").fill(kind.equals("maintenance")?"Service maintenance":"Release freeze");form.getByLabel("Window type").selectOption(kind);form.getByLabel("Business calendar").selectOption(kind.equals("maintenance")?"Maintenance":"Freeze");form.getByRole(AriaRole.BUTTON,new Locator.GetByRoleOptions().setName("Add window")).press("Enter");}var freeze=page.locator("section[id^='window-']").filter(new Locator.FilterOptions().setHas(page.getByRole(AriaRole.HEADING,new Page.GetByRoleOptions().setName("Release freeze").setExact(true))));freeze.getByLabel("Window name").fill("Reviewed release freeze");freeze.getByRole(AriaRole.BUTTON,new Locator.GetByRoleOptions().setName("Save window")).press("Enter");ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/change-windows-light.png")).setFullPage(true));
   page.navigate(h.base()+"/record/change_request/"+id);page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Review change schedule")).press("Enter");page.getByLabel("Item summary").fill("Payment service");page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Search items")).press("Enter");assertTrue(page.locator("main").textContent().contains("Set the proposed interval"),page.locator("main").textContent());page.getByLabel("Configuration item").selectOption(ci);page.getByLabel("Planned start (UTC)").fill("2026-11-18T09:30:00Z");page.getByLabel("Planned end (UTC)").fill("2026-11-18T10:30:00Z");page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Save proposed schedule")).press("Enter");assertThat(page.locator("main")).containsText("Blackout: Reviewed release freeze");assertThat(page.locator("main script")).hasCount(0);
   for(String theme:List.of("light","dark")){if(theme.equals("dark")){page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Dark mode").setExact(true)).click();page.setViewportSize(390,844);}ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/change-schedule-"+theme+".png")).setFullPage(true));}
   page.getByLabel("Planned start (UTC)").fill("2026-11-18T11:00:00Z");page.getByLabel("Planned end (UTC)").fill("2026-11-18T12:00:00Z");page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Save proposed schedule")).press("Enter");assertThat(page.locator("main")).containsText("No current scheduling conflicts");page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Clear schedule")).press("Enter");assertThat(page.locator("main")).containsText("no CI reservation");page.getByLabel("Configuration item").selectOption(ci);page.getByLabel("Planned start (UTC)").fill("2026-11-18T11:00:00Z");page.getByLabel("Planned end (UTC)").fill("2026-11-18T12:00:00Z");page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Save proposed schedule")).press("Enter");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Review change plan").setExact(true)).press("Enter");page.getByLabel("Review decision").selectOption("true");page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Save change plan")).press("Enter");assertThat(page.locator("main")).containsText("Ready for the current change details");page.navigate(h.base()+"/record/change_request/"+id);for(String state:List.of("review","approved","implement")){page.getByLabel("State").selectOption(state);page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Save changes →")).press("Enter");assertThat(page.locator("form input[name='revision']").first()).not().hasValue("0");}page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Review change schedule").setExact(true)).press("Enter");assertThat(page.locator("main")).containsText("Return the change to draft or rejected");assertThat(page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Save proposed schedule"))).hasCount(0);
   page.navigate(h.base()+"/admin/change-windows/"+ci);page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Remove window: Reviewed release freeze").setExact(true)).press("Enter");assertThat(page.getByRole(AriaRole.HEADING,new Page.GetByRoleOptions().setName("Reviewed release freeze").setExact(true))).hasCount(0);
  }
 }
}
